class Bad {
    fun bad(conMgr: Any?): HttpClient {
        return HttpClientBuilder.create() // bad, missing setMaxConnPerRoute and setMaxConnTotal
            .build()
    }
}

class Good {
    fun good(conMgr: Any?): HttpClient {
        return HttpClientBuilder.create()
            .setConnectionManager(conMgr) // delegated to conMgr
            .build()
    }
}

class Good2 {
    fun good(conMgr: Any?): HttpClient {
        return HttpClients.custom()
            .setMaxConnPerRoute(MAX_CONNECTIONS_PER_ROUTE)
            .setMaxConnTotal(MAX_CONNECTIONS_TOTAL)
            .build()
    }
}

internal class Bad2 {
    fun bad(conMgr: Any?): CloseableHttpClient {
        val httpClientBuilder = HttpClients.custom() // bad
            //.setConnectionManager(null)
        return httpClientBuilder.build()
    }
}

class BadMgr {
    fun connectionManager(): PoolingHttpClientConnectionManager {
        val cm = PoolingHttpClientConnectionManager() // bad
        return cm
    }
}

class GoodMgr {
    fun connectionManager(): PoolingHttpClientConnectionManager {
        val cm = PoolingHttpClientConnectionManager()
        cm.setMaxTotal(100)
        cm.setDefaultMaxPerRoute(50)
        return cm
    }
}

class BadMgr5Async {
    fun connectionManager(): PoolingAsyncClientConnectionManager {
        val cm = PoolingAsyncClientConnectionManager() // bad
        return cm
    }
}

class GoodMgr5Async {
    fun connectionManager(): PoolingAsyncClientConnectionManager {
        val cm = PoolingAsyncClientConnectionManager()
        cm.setMaxTotal(100)
        cm.setDefaultMaxPerRoute(50)
        return cm
    }
}
